<section class="section-space"><div class="container-wide method-layout"><aside><div class="eyebrow"><span>{{ tval($data['eyebrow']) }}</span></div><h2>{{ ml($data['title']) }}</h2>@if ($data['image'])<img alt="{{ tval($data['image_alt']) }}" height="1000" loading="lazy" src="{{ media_url($data['image']) }}" width="1500"/>@endif</aside><div>@foreach ($data['items'] as $index => $item)<article class="method-row reveal"><span class="method-number">{{ str_pad($index + 1, 2, '0', STR_PAD_LEFT) }}</span><div><h2>{{ tval($item['title'] ?? '') }}</h2><p>{{ tval($item['text'] ?? '') }}</p>@if (filled(tval($item['tags'] ?? '')))<small>{{ tval($item['tags']) }}</small>@endif</div></article>@endforeach</div></div></section>
